#!/usr/bin/env python3
"""Generate internal/cli/i18n/catalog_gen.go from schema/i18n/cli.*.json."""

import json
import os
import subprocess
import sys

ROOT = os.path.join(os.path.dirname(__file__), "..", "..")
CATALOG_DIR = os.path.join(ROOT, "schema", "i18n")
OUTPUT_PATH = os.path.join(ROOT, "internal", "cli", "i18n", "catalog_gen.go")

LANGUAGES = ["en", "zh-CN"]


def go_string(value):
    return json.dumps(value, ensure_ascii=False)


def generate():
    lines = [
        "// Code generated by scripts/schema/gen-cli-i18n.py; DO NOT EDIT.",
        "",
        "package i18n",
        "",
        "var catalog = map[string]map[string]string{",
    ]
    for lang in LANGUAGES:
        path = os.path.join(CATALOG_DIR, f"cli.{lang}.json")
        messages = json.loads(open(path, encoding="utf-8").read())
        lines.append(f'\t"{lang}": {{')
        for key in sorted(messages):
            lines.append(f"\t\t{go_string(key)}: {go_string(messages[key])},")
        lines.append("\t},")
    lines.append("}")
    lines.append("")

    with open(OUTPUT_PATH, "w", encoding="utf-8", newline="\n") as f:
        f.write("\n".join(lines))

    result = subprocess.run(["gofmt", "-w", OUTPUT_PATH], capture_output=True, text=True, encoding="utf-8")
    if result.returncode != 0:
        sys.stderr.write(result.stderr)
        raise SystemExit(result.returncode)
    print(f"Generated {OUTPUT_PATH}")


if __name__ == "__main__":
    generate()
